// Generates typed artifacts from protocol/registry/justslide.protocol.v1.json.
//   bun protocol/scripts/gen.ts          -> write files
//   bun protocol/scripts/gen.ts --check  -> exit 1 if generated files drift
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';

const root = join(import.meta.dir, '..', '..');
const registryPath = join(root, 'protocol/registry/justslide.protocol.v1.json');
const reg = JSON.parse(readFileSync(registryPath, 'utf8'));
const header = (c: string) =>
  `${c} GENERATED by protocol/scripts/gen.ts from protocol/registry/justslide.protocol.v1.json.\n${c} Do not edit by hand. Protocol ${reg.protocol} v${reg.version}.\n`;

type Schema = Record<string, any>;
function tsType(s: Schema, indent = ''): string {
  if (!s) return 'unknown';
  if (s.$ref) return s.$ref.split('/').pop();
  if ('const' in s) return JSON.stringify(s.const);
  if (s.enum) return s.enum.map((v: unknown) => JSON.stringify(v)).join(' | ');
  if (s.oneOf) return s.oneOf.map((x: Schema) => tsType(x, indent)).join(' | ');
  switch (s.type) {
    case 'string': return 'string';
    case 'integer': case 'number': return 'number';
    case 'boolean': return 'boolean';
    case 'array': return `Array<${tsType(s.items ?? {}, indent)}>`;
    case 'object': {
      const props = s.properties ?? {};
      const req = new Set<string>(s.required ?? []);
      const keys = Object.keys(props);
      if (!keys.length) return s.additionalProperties === false ? 'Record<string, never>' : 'Record<string, unknown>';
      const inner = indent + '  ';
      return `{\n${keys.map(k => `${inner}${props[k].description ? `/** ${props[k].description} */ ` : ''}${k}${req.has(k) ? '' : '?'}: ${tsType(props[k], inner)};`).join('\n')}\n${indent}}`;
    }
    default: return 'unknown';
  }
}

function genTs(): string {
  const out: string[] = [header('//')];
  out.push(`export const PROTOCOL_NAME = ${JSON.stringify(reg.protocol)} as const;`);
  out.push(`export const PROTOCOL_VERSION = ${JSON.stringify(reg.version)} as const;`);
  out.push(`export const LIMITS = ${JSON.stringify(reg.limits, null, 2)} as const;`);
  out.push(`export const FRAMING = ${JSON.stringify(reg.framing, null, 2)} as const;`);
  for (const [name, schema] of Object.entries<Schema>(reg.definitions)) {
    out.push(`export type ${name} = ${tsType(schema)};`);
  }
  out.push(`export type ErrorCode = Error['code'];`);
  out.push(`export type Operation = ${Object.keys(reg.operations).map(o => JSON.stringify(o)).join(' | ')};`);
  out.push('export interface CommandMap {');
  for (const c of reg.commands) {
    out.push(`  ${JSON.stringify(c.name)}: {\n    args: ${tsType(c.arguments, '    ')};\n    result: ${tsType(c.result, '    ')};\n  };`);
  }
  out.push('}');
  out.push('export type CommandName = keyof CommandMap;');
  const meta = reg.commands.map((c: Schema) => ({ name: c.name, mcpTool: c.mcpTool, title: c.title, operation: c.operation, idempotency: c.idempotency, activates: c.activates, events: c.events }));
  out.push(`export const COMMANDS = ${JSON.stringify(meta, null, 2)} as const;`);
  out.push(`export type EventName = ${reg.events.map((e: Schema) => JSON.stringify(e.name)).join(' | ')};`);
  return out.join('\n\n') + '\n';
}

function cppIdent(name: string) {
  return 'k' + name.split(/[._-]/).map(p => p[0].toUpperCase() + p.slice(1)).join('');
}
function genCpp(): string {
  const g = 'JUSTSLIDE_BROWSER_AUTOMATION_PROTOCOL_CONSTANTS_H_';
  const o: string[] = [header('//'), `#ifndef ${g}\n#define ${g}\n\n#include <cstddef>\n#include <cstdint>\n\nnamespace justslide::protocol {\n`];
  o.push(`inline constexpr char kProtocolName[] = "${reg.protocol}";`);
  o.push(`inline constexpr char kProtocolVersion[] = "${reg.version}";`);
  o.push(`inline constexpr int kEnvelopeVersion = 1;`);
  o.push(`inline constexpr size_t kMaxFrameBytes = ${reg.framing.maxFrameBytes};`);
  o.push(`inline constexpr size_t kMaxResultFrameBytes = ${reg.framing.maxResultFrameBytes};`);
  for (const [k, v] of Object.entries<number>(reg.limits)) o.push(`inline constexpr int ${cppIdent(k)} = ${v};`);
  o.push('\n// Commands.');
  for (const c of reg.commands) o.push(`inline constexpr char ${cppIdent('cmd.' + c.name)}[] = "${c.name}";`);
  o.push('\n// Operations (grant scopes).');
  for (const op of Object.keys(reg.operations)) o.push(`inline constexpr char ${cppIdent('op.' + op)}[] = "${op}";`);
  o.push('\n// Error codes.');
  for (const e of reg.definitions.Error.properties.code.enum) o.push(`inline constexpr char ${cppIdent('err.' + e)}[] = "${e}";`);
  o.push('\n// Events.');
  for (const e of reg.events) o.push(`inline constexpr char ${cppIdent('evt.' + e.name)}[] = "${e.name}";`);
  o.push(`\n}  // namespace justslide::protocol\n\n#endif  // ${g}`);
  return o.join('\n') + '\n';
}

const targets: Record<string, string> = {
  'protocol/generated/protocol.ts': genTs(),
  'browser/integration/justslide/automation/protocol_constants.h': genCpp(),
};
const check = process.argv.includes('--check');
let drift = 0;
for (const [rel, content] of Object.entries(targets)) {
  const p = join(root, rel);
  if (check) {
    if (!existsSync(p) || readFileSync(p, 'utf8') !== content) { console.error(`drift: ${rel} (run: bun run protocol:gen)`); drift++; }
  } else {
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, content);
    console.error(`wrote ${relative(root, p)}`);
  }
}
if (check) { if (drift) process.exit(1); console.error('protocol: generated files up to date'); }
